#pragma once

// LOCAL BUILD ONLY, never part of a pull request.
// The label of a rig build, shown in the window header, the window title and
// the OSD's first row: the build identity (the branch), then the first 8
// characters of the full commit, the same 8 that name the build's drop folder.
// VERSION_COMMIT_SHORT holds only 7, so the 8 are read from the end of
// VERSION_URL, which ends with the full commit.
// version.h is generated by the GUI build only; include this header only from
// GUI files that the test project does not compile.

#include <string>
#include <BuildIdentityPolicy.h>
#include "version.h"

namespace LocalBuildLabel
{
	inline std::wstring Text()
	{
		const std::wstring identity = BuildIdentityPolicy::Format(
			VERSION_BRANCH, VERSION_COMMIT_SHORT, VERSION_DESCRIBE, false);
		const std::wstring url(VERSION_URL);
		const size_t slash = url.find_last_of(L'/');
		const std::wstring commit = slash == std::wstring::npos ?
			std::wstring() : url.substr(slash + 1, 8);
		return commit.empty() ? identity : identity + L" @ " + commit;
	}
}
